// Turns the uploaded photo into a picture the API can read, and reads the form.
const item = $input.first();
const files = item.binary || {};
const key = Object.keys(files)[0];
if (!key) throw new Error('Add a product photo to the form.');
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
// A request can be up to 10 MB, and a photo grows by a third when it is sent as text.
if (buffer.length > 7 * 1024 * 1024) {
  throw new Error('The photo is bigger than 7 MB. Use a smaller photo, for example a screenshot of it.');
}
const type = files[key].mimeType || 'image/jpeg';
if (!/^image\/(png|jpe?g|webp)$/.test(type)) {
  throw new Error('Use a JPG, PNG or WebP photo.');
}
const form = item.json;
return [{
  json: {
    product: String(form['Product name'] || '').trim(),
    brief: String(form['What should the ad say?'] || '').trim(),
    seconds: parseInt(String(form['Video length'] || '5'), 10),
    audio: !String(form['Voice and sound'] || 'Yes').startsWith('No'),
    image: `data:${type};base64,${buffer.toString('base64')}`,
  },
}];

