// Reads the script the model wrote. Models sometimes wrap JSON in ``` fences.
const reply = $input.first().json;
const text = reply.choices?.[0]?.message?.content || '';
let plan;
try {
  plan = JSON.parse(text.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
} catch (e) {
  throw new Error('The script model did not answer in the expected shape. Run the workflow again, or pick another script model in Settings.');
}
if (!plan.video_prompt) throw new Error('The script model returned no video prompt. Run the workflow again.');
return [{ json: { ...plan, script_cost_usd: reply.usage?.cost_usd ?? null } }];

